const labels={done:'已完成',active:'进行中',pending:'待验收'};
async function refreshProgress(){try{const response=await fetch('/progress.json?time='+Date.now(),{cache:'no-store'});if(!response.ok)throw new Error();const data=await response.json();document.getElementById('percent').textContent=data.percent;document.getElementById('fill').style.width=data.percent+'%';document.querySelector('[role="progressbar"]').setAttribute('aria-valuenow',data.percent);document.getElementById('summary').textContent=data.summary;document.getElementById('phase').textContent=data.phase;document.getElementById('updated').textContent='最近更新：'+data.updated;const list=document.getElementById('stages');list.replaceChildren();data.stages.forEach((stage,index)=>{const row=document.createElement('div');row.className='stage '+stage.status;const icon=document.createElement('span');icon.className='indicator';icon.textContent=stage.status==='done'?'✓':String(index+1);const content=document.createElement('div');const title=document.createElement('strong');title.textContent=stage.title;const detail=document.createElement('p');detail.textContent=stage.detail;content.append(title,detail);const status=document.createElement('span');status.className='label';status.textContent=labels[stage.status];row.append(icon,content,status);list.append(row);});const health=await fetch('/api/health',{cache:'no-store'}).then(r=>r.json());document.getElementById('connection').textContent=health.simulator?.connected?'● 网页、业务后端与设备模拟器均在线':'● 网页在线，设备模拟器正在连接';}catch{document.getElementById('connection').textContent='连接暂不可用，稍后自动重试';}}
refreshProgress();setInterval(refreshProgress,5000);
